// The capsule icon family (Aura v65: Ikonlar, IkonlarYeni and IkonlarRevize, the one icon family of
// the app, U6) → apps/mobile/src/theme/capIcons.generated.ts, drawn by
// apps/mobile/src/aura/CapIcon.tsx. The drawings are docs/design/aura/ikonlar/<name>.svg, each part
// marked with its layer (`data-layer`): a strong, b the body at half opacity, o a ring (3 wide),
// ob a soft line, sa and sb a stroked line in a's and b's colour (round ends), w a surface dot.
// `node --experimental-strip-types scripts/sistem/capIcons.ts`; capIcons.test.ts checks the
// generated file against the drawings.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const LAYERS = ['a', 'b', 'o', 'ob', 'sa', 'sb', 'w'] as const;
const KEEP = ['x', 'y', 'width', 'height', 'rx', 'cx', 'cy', 'r', 'd', 'transform', 'stroke-width'];
const NUMERIC = new Set(['x', 'y', 'width', 'height', 'rx', 'cx', 'cy', 'r', 'stroke-width']);

export const ICON_DIR = 'docs/design/aura/ikonlar';
export const GENERATED = 'apps/mobile/src/theme/capIcons.generated.ts';

type Part = Record<string, string | number>;

export function parseIcon(svg: string, name: string): Part[] {
  const parts: Part[] = [];
  for (const m of svg.matchAll(/<(rect|circle|path)\b([^>]*?)\/?>/g)) {
    const attrs = Object.fromEntries(
      [...(m[2] ?? '').matchAll(/([\w-]+)="([^"]*)"/g)].map((a) => [a[1], a[2]]),
    ) as Record<string, string>;
    const layer = attrs['data-layer'];
    if (!layer || !(LAYERS as readonly string[]).includes(layer)) {
      throw new Error(`${name}: a part without a known data-layer`);
    }
    const part: Part = { t: m[1] as string, l: layer };
    for (const key of KEEP) {
      const v = attrs[key];
      if (v === undefined) continue;
      part[key === 'stroke-width' ? 'sw' : key] = NUMERIC.has(key) ? Number(v) : v;
    }
    parts.push(part);
  }
  if (parts.length === 0) throw new Error(`${name}: no parts`);
  return parts;
}

export function capIconsSource(root: string): string {
  const dir = join(root, ICON_DIR);
  const names = readdirSync(dir)
    .filter((f) => f.endsWith('.svg'))
    .map((f) => f.slice(0, -4))
    .sort();
  const body = names
    .map((name) => {
      const parts = parseIcon(readFileSync(join(dir, `${name}.svg`), 'utf8'), name);
      return `  ${name}: [\n${parts.map((p) => `    ${JSON.stringify(p)},`).join('\n')}\n  ],`;
    })
    .join('\n');
  return `// Generated by scripts/sistem/capIcons.ts from ${ICON_DIR}/*.svg (Aura v65).\n// Do not edit; run the script.\nexport const CAP_ICONS = {\n${body}\n} as const;\n`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const root = process.cwd();
  writeFileSync(join(root, GENERATED), capIconsSource(root));
}
